function fxUsd(value, kursUsd) {
  return Number(kursUsd) ? (Number(value) / kursUsd).toFixed(2) : '0.00';
}

function fxEur(value, kursEur) {
  return Number(kursEur) ? (Number(value) / kursEur).toFixed(2) : '0.00';
}

/** Baris waterfall COGS — sama dengan UI Langkah Demi Langkah */
function buildCogsWaterfallRows(cogsData, cogsConfig) {
  const cd = cogsData || {};
  const cc = cogsConfig || {};
  const jalur = cc.packingJalur || 'BOX';
  const afterMat = cd.totalMaterial || 0;
  const afterProc = afterMat + (cd.totalProcess || 0);
  const sellingRounded = cd.sellingPrice ?? Math.floor((cd.sellingPriceRaw || cd.sellingPrice || 0) / 1000) * 1000;

  return [
    {
      step: 1,
      komponen: 'Bahan Baku & Material (RAW)',
      sumber: 'Harga Part × Qty + Penyesuaian SF/WF | Engine BOM Rollup',
      nilai: afterMat,
      running: afterMat,
    },
    {
      step: 2,
      komponen: 'Proses Pabrik (Work Center & Labor)',
      sumber: 'Total Waktu × (Tarif Mesin + Upah Karyawan) | Costing Studio (Proses)',
      nilai: cd.totalProcess || 0,
      running: afterProc,
    },
    {
      step: 3,
      komponen: `Biaya Packing (${jalur})`,
      sumber: `Material ${jalur === 'BOX' ? 'Karton Luar' : 'Single Face'} + Tenaga Packing | Mat: ${cd.packingMat ?? 0} | Labor: ${cd.packingLab ?? 0}`,
      nilai: cd.packingCost || 0,
      running: cd.productionCost || 0,
    },
    {
      step: '',
      komponen: 'RAW Production Cost',
      sumber: `Material + Proses Pabrik + Packing (${jalur})`,
      nilai: '',
      running: cd.productionCost || 0,
      highlight: 'subtotal',
    },
    {
      step: 4,
      komponen: 'Factory Overhead',
      sumber: `Production Cost × ${cc.factoryOhPct ?? 0}%`,
      nilai: cd.factoryOh || 0,
      running: (cd.productionCost || 0) + (cd.factoryOh || 0),
    },
    {
      step: 5,
      komponen: 'Management Overhead',
      sumber: `Production Cost × ${cc.managementOhPct ?? 0}%`,
      nilai: cd.managementOh || 0,
      running: cd.totalCogs || 0,
    },
    {
      step: '',
      komponen: `TOTAL COGS (${jalur})`,
      sumber: 'Production Cost + Factory OH + Management OH',
      nilai: '',
      running: cd.totalCogs || 0,
      highlight: 'total',
    },
    {
      step: '',
      komponen: 'Harga Jual FOB',
      sumber: `COGS × (1 + ${cc.markupPct ?? 0}% Markup) | Dibulatkan ribuan`,
      nilai: '',
      running: sellingRounded,
      highlight: 'selling',
    },
  ];
}

function safeFilename(base) {
  return String(base || 'BOM')
    .replace(/[^\w\-]+/g, '_')
    .replace(/_+/g, '_')
    .slice(0, 80);
}

function stamp() {
  return new Date().toISOString().slice(0, 10);
}

function sumRows(rows, key) {
  return rows.reduce((acc, r) => acc + (Number(r[key]) || 0), 0);
}

function buildPackingPayload({
  dimensi,
  packingDimensions = [],
  packingSpec = {},
  containerCapacity = [],
  volBoxPacking,
  volSFPacking,
}) {
  const dim = dimensi || {};
  const volProduk = ((Number(dim.w) || 0) * (Number(dim.d) || 0) * (Number(dim.h) || 0)) / 1_000_000_000;

  const dimensionRows = (packingDimensions || []).map((item) => {
    const grossW = (Number(dim.w) || 0) + (Number(item.tolW) || 0);
    const grossD = (Number(dim.d) || 0) + (Number(item.tolD) || 0);
    const grossH = (Number(dim.h) || 0) + (Number(item.tolH) || 0);
    const vol = (grossW * grossD * grossH) / 1_000_000_000;
    return {
      type: item.type || '',
      grossW,
      grossD,
      grossH,
      grossDim: `${grossW} x ${grossD} x ${grossH}`,
      tolW: item.tolW ?? 0,
      tolD: item.tolD ?? 0,
      tolH: item.tolH ?? 0,
      vol: Number(vol.toFixed(6)),
      chairFactor: item.chairFactor ? 'Ya' : 'Tidak',
    };
  });

  const mapMaterial = (list, jalur) =>
    (list || []).map((m, i) => {
      const qty = Number(m.qty) || 0;
      const harga = Number(m.harga) || 0;
      return {
        no: i + 1,
        jalur,
        nama: m.nama || '',
        qty,
        unit: m.unit || '',
        harga,
        total: qty * harga,
      };
    });

  const materialRows = [
    ...mapMaterial(packingSpec.materialsBox, 'Box Karton'),
    ...mapMaterial(packingSpec.materialsSF, 'Single Face'),
  ];

  const mapRouting = (list, jalur) =>
    (list || []).map((r, i) => {
      const waktu = Number(r.waktu) || 0;
      const pekerja = Number(r.pekerja) || 0;
      const rate = Number(r.rate) || 0;
      return {
        no: i + 1,
        jalur,
        nama: r.nama || '',
        waktu,
        pekerja,
        rate,
        orgMenit: waktu * pekerja,
        total: waktu * pekerja * rate,
      };
    });

  const routingRows = [
    ...mapRouting(packingSpec.routingBox, 'Box Karton'),
    ...mapRouting(packingSpec.routingSF, 'Single Face'),
  ];

  const containerRows = (containerCapacity || [])
    .filter((c) => !c.hidden)
    .map((c, i) => ({
      no: i + 1,
      type: c.type || '',
      netCapBox: c.netCapBox ?? '',
      netCapSF: c.netCapSF ?? '',
      matCostBox: Number(c.matCostBox) || 0,
      matCostSF: Number(c.matCostSF) || 0,
      routCostBox: Number(c.routCostBox) || 0,
      routCostSF: Number(c.routCostSF) || 0,
      mgtOvBox: Number(c.mgtOvBox) || 0,
      mgtOvSF: Number(c.mgtOvSF) || 0,
      totalBox: Number(c.totalBox) || 0,
      totalSF: Number(c.totalSF) || 0,
    }));

  const totals = {
    packBoxMat: sumRows(materialRows.filter((m) => m.jalur === 'Box Karton'), 'total'),
    packSfMat: sumRows(materialRows.filter((m) => m.jalur === 'Single Face'), 'total'),
    packBoxLab: sumRows(routingRows.filter((r) => r.jalur === 'Box Karton'), 'total'),
    packSfLab: sumRows(routingRows.filter((r) => r.jalur === 'Single Face'), 'total'),
  };
  totals.packMat = totals.packBoxMat + totals.packSfMat;
  totals.packLab = totals.packBoxLab + totals.packSfLab;
  totals.packGrand = totals.packMat + totals.packLab;

  return {
    volProduk: Number(volProduk.toFixed(6)),
    volBoxPacking,
    volSFPacking,
    dimensionRows,
    materialRows,
    routingRows,
    containerRows,
    totals,
  };
}

/** Susun data export dari state editor */
export function buildBomExportPayload({
  productInfo,
  productMeta,
  productImage,
  dimensi,
  bomData,
  flatNodes,
  cogsData,
  cogsConfig,
  kursUsd,
  kursEur,
  volBoxPacking,
  volSFPacking,
  summaryTotals,
  materialTabTotals,
  prosesTabTotals,
  packingDimensions,
  packingSpec,
  containerCapacity,
  customErp,
}) {
  const dim = dimensi || {};
  const volProduk =
    ((Number(dim.w) || 0) * (Number(dim.d) || 0) * (Number(dim.h) || 0)) / 1_000_000_000;

  const partQtyByKode = {};
  flatNodes
    .filter((n) => n.data.tipe === 'PART')
    .forEach((n) => {
      partQtyByKode[n.data.kode] = Number(n.data.qty) || 1;
    });
  const prosesEntries = [];
  flatNodes.forEach((node) => {
    expandProsesList(node.data).forEach((p) => {
      prosesEntries.push({
        ...p,
        nodeId: node.id,
        nodeNama: node.data.nama,
        nodeKode: node.data.kode,
      });
    });
  });
  const prosesLines = flattenProsesLineItems(prosesEntries);
  const prosesTotals = sumProsesLineItems(prosesLines);

  const strukturRows = flatNodes.map((node, i) => {
    const d = node.data;
    const fin = d.tipe === 'PART' ? computePartDisplayFinancials(d, kursUsd, kursEur) : null;
    return {
      no: i + 1,
      level: node.level,
      tipe: d.tipe,
      materialType: d.tipe === 'PART' ? getMaterialTypeLabel(d.materialType) : '',
      kode: d.kode || '',
      nama: d.nama || '',
      qty: d.qty ?? '',
      unit: d.unit || (d.tipe === 'PART' ? 'EA' : ''),
      dimensi: d.p && d.l && d.t ? `${d.p} x ${d.l} x ${d.t}` : '',
      vol: d.vol ?? '',
      biayaIdr: fin?.unitMat ?? 0,
      biayaUsd: fin?.usdMat ?? '',
      biayaEur: fin?.eurMat ?? '',
      prodIdr: fin?.prodTotal ?? 0,
      prodUsd: fin?.usdProd ?? '',
      prodEur: fin?.eurProd ?? '',
      prodUnitIdr: fin?.prodUnit ?? '',
      prodUnitUsd: fin?.usdProdUnit ?? '',
      prodUnitEur: fin?.eurProdUnit ?? '',
      sf: Number(d.sf) || 0,
      wf: Number(d.wf) || 0,
      prosesCount: d.proses?.length || d.proses_count || 0,
      catatan: d.catatan || '',
    };
  });

  const strukturTotals = {
    matIdr: sumRows(
      strukturRows.filter((r) => r.tipe === 'PART'),
      'biayaIdr',
    ),
    prodIdr: sumRows(strukturRows.filter((r) => r.tipe === 'PART'), 'prodIdr'),
  };

  const materialRows = flatNodes
    .filter((n) => n.data.tipe === 'PART')
    .map((node, i) => {
      const d = node.data;
      const hierarchy = getPartHierarchyLabels(bomData, node.id);
      const sf = Number(d.sf) || 0;
      const wf = Number(d.wf) || 0;
      const row = computePartCostRow(d);
      const fin = computePartDisplayFinancials(d, kursUsd, kursEur);
      const matTotal = row.matAdjusted;
      return {
        no: i + 1,
        modul: hierarchy.modul?.nama || '',
        modulKode: hierarchy.modul?.kode || '',
        submodul: hierarchy.submodul?.nama || '',
        submodulKode: hierarchy.submodul?.kode || '',
        submodul2: hierarchy.submodul2?.nama || '',
        submodul2Kode: hierarchy.submodul2?.kode || '',
        materialType: getMaterialTypeLabel(d.materialType),
        kode: d.kode || '',
        nama: d.nama || '',
        vendor: d.vendor || '',
        sf,
        wf,
        dimensi: `${d.p || 0} x ${d.l || 0} x ${d.t || 0}`,
        vol: d.vol ?? '',
        qty: d.qty ?? '',
        unit: d.unit || 'EA',
        matIdr: fin.unitMat,
        matTotalIdr: matTotal,
        matUsd: fin.usdMat,
        matEur: fin.eurMat,
        prodIdr: fin.prodTotal,
        prodUsd: fin.usdProd,
        prodEur: fin.eurProd,
        prodUnitIdr: fin.prodUnit,
        prodUnitUsd: fin.usdProdUnit,
        prodUnitEur: fin.eurProdUnit,
      };
    });

  const materialTotals = {
    matIdr: sumRows(materialRows, 'matIdr'),
    matTotalIdr: sumRows(materialRows, 'matTotalIdr'),
    prodIdr: sumRows(materialRows, 'prodIdr'),
    partCount: materialRows.length,
    totalQty: materialRows.reduce((s, r) => s + (Number(r.qty) || 0), 0),
  };

  const prosesRows = prosesLines.map((ln, i) => {
    const partQty = partQtyByKode[ln.nodeKode] || 1;
    const prodUnit = ln.biayaTotal / partQty;
    return {
      no: i + 1,
      partKode: ln.nodeKode,
      partNama: ln.nodeNama,
      partQty,
      operasi: ln.opNama,
      tipe: ln.inputMode === 'routing' ? 'Routing' : 'Work Center',
      tahap: ln.mfgProcess || '',
      wcLangkah: ln.stepUrutan != null ? `#${ln.stepUrutan} ${ln.wcNama}` : ln.wcNama,
      durasi: ln.waktu,
      pekerja: ln.person,
      orgMenit: ln.waktu * ln.person,
      biayaWc: ln.biayaMesin,
      biayaTk: ln.biayaPekerja,
      subtotal: ln.biayaTotal,
      subtotalUsd: fxUsd(ln.biayaTotal, kursUsd),
      subtotalEur: fxEur(ln.biayaTotal, kursEur),
      prodUnitIdr: prodUnit,
      prodUnitUsd: fxUsd(prodUnit, kursUsd),
      prodUnitEur: fxEur(prodUnit, kursEur),
      detail: ln.note || '',
    };
  });

  const cogsWaterfall = buildCogsWaterfallRows(cogsData, cogsConfig);
  const summaryCost = computeSummaryCostRollup({ bomData, cogsData, cogsConfig });
  const summaryKalkulasiRows = buildSummaryKalkulasiRows(flatNodes);
  const erpRows = buildErpExportRows({ flatNodes, customErp: customErp || {} });

  const packing = buildPackingPayload({
    dimensi,
    packingDimensions,
    packingSpec,
    containerCapacity,
    volBoxPacking,
    volSFPacking,
  });

  return {
    meta: {
      filename: safeFilename(productInfo?.kode || productInfo?.namaBom || 'BOM'),
      exportedAt: new Date().toLocaleString('id-ID'),
    },
    productInfo,
    productMeta,
    productImage: productImage || '',
    dimensi,
    volProduk: Number(volProduk.toFixed(6)),
    volBoxPacking,
    volSFPacking,
    kursUsd,
    kursEur,
    cogsData,
    cogsConfig,
    cogsWaterfall,
    summaryTotals,
    materialTabTotals,
    prosesTabTotals,
    prosesTotals,
    strukturRows,
    strukturTotals,
    materialRows,
    materialTotals,
    prosesRows,
    packing,
    summaryCost,
    summaryKalkulasiRows,
    erpRows,
  };
}

function buildSummaryKalkulasiRows(flatNodes) {
  return flatNodes.map((node, i) => {
    const d = node.data;
    const fin = d.tipe === 'PART' ? computePartCostRow(d) : null;
    return {
      no: i + 1,
      level: node.level,
      tipe: d.tipe,
      kode: d.kode || '',
      nama: d.nama || '',
      qty: d.qty ?? '',
      matIdr: fin?.matAdjusted ?? 0,
      prosesIdr: fin?.prosesTotal ?? 0,
      totalIdr: fin?.biayaProduksi ?? 0,
    };
  });
}

function buildErpExportRows({ flatNodes, customErp }) {
  const rows = [];
  flatNodes.forEach((node) => {
    const d = node.data;
    if (d.tipe !== 'PART') return;
    const fin = computePartCostRow(d);
    rows.push({
      sumber: 'BOM',
      tipe: 'Material Part',
      referensi: d.kode,
      nama: d.nama,
      qty: d.qty,
      nilai: fin.matAdjusted,
    });
    expandProsesList(d).forEach((p) => {
      const c = calcProsesCosts(p);
      rows.push({
        sumber: 'BOM',
        tipe: 'Proses',
        referensi: p.nama || '—',
        nama: d.nama,
        qty: 1,
        nilai: c.total,
      });
    });
  });
  (customErp.parts || []).forEach((item) => {
    rows.push({
      sumber: 'Custom',
      tipe: 'Part',
      referensi: item.id,
      nama: item.nama,
      qty: item.qty,
      nilai: (Number(item.qty) || 0) * (Number(item.rate) || 0),
    });
  });
  (customErp.machines || []).forEach((item) => {
    rows.push({
      sumber: 'Custom',
      tipe: 'Mesin',
      referensi: item.id,
      nama: item.nama,
      qty: item.waktu,
      nilai: (Number(item.waktu) || 0) * (Number(item.rate) || 0),
    });
  });
  (customErp.workers || []).forEach((item) => {
    rows.push({
      sumber: 'Custom',
      tipe: 'TK',
      referensi: item.id,
      nama: item.nama,
      qty: item.waktu,
      nilai: (Number(item.waktu) || 0) * (Number(item.person) || 0) * (Number(item.rate) || 0),
    });
  });
  return rows;
}

function sheetFromAoA(rows) {
  return XLSX.utils.aoa_to_sheet(rows);
}

function appendSheet(wb, name, rows) {
  XLSX.utils.book_append_sheet(wb, sheetFromAoA(rows), name.slice(0, 31));
}

